import json
from collections.abc import Iterable
from pathlib import Path

import numpy as np

from .subway import Train

# Generated by scripts/build_subway_map.py
_DATA = json.loads((Path(__file__).parent / "subway_map.json").read_text())
_MAX_NUDGE = 2

TRACKS = np.array([[cell == "#" for cell in row] for row in _DATA["tracks"]])
_TRACK_PIXELS = np.argwhere(TRACKS)

Pixel = tuple[int, int]


def project(lat: float, lon: float) -> tuple[float, float]:
    return float(np.interp(lat, _DATA["lat"], _DATA["y"])), float(np.interp(lon, _DATA["lon"], _DATA["x"]))


def place_trains(trains: Iterable[Train]) -> dict[Pixel, Train]:
    """Puts each train on the nearest (row, column) of track, nudging it along if that pixel is taken."""
    placed: dict[Pixel, Train] = {}
    for train in sorted(trains, key=lambda train: train.id):
        distances = np.hypot(*(_TRACK_PIXELS - project(train.lat, train.lon)).T)
        for index in np.argsort(distances, kind="stable"):
            if distances[index] > _MAX_NUDGE:
                break
            row, column = _TRACK_PIXELS[index].tolist()
            if (row, column) not in placed:
                placed[row, column] = train
                break
    return placed
